Clojure, Midje.rag_lambda:
lambda { |stdout,stderr,status|
  output = stdout + stderr
  return :red if /^FAILURE: .* failed./.match(output)

  # load-facts runs any clojure.test deftest alongside the midje checkables and
  # reports them in a section of their own, which the midje summary above says
  # nothing about. A learner who writes deftest and is, rather than midje's
  # arrow, has their failures counted only here.
  if match = /^(\d+) failures, (\d+) errors\./.match(output)
    return :red if match[1] != '0' || match[2] != '0'
  end

  return :green if /^All checks .* succeeded./.match(output)
  return :amber
}

Clojure, clojure.test.rag_lambda:
lambda { |stdout,stderr,status|
  output = stdout + stderr
  syntax_error_pattern = /Exception in thread/
  ran_pattern = /Ran (\d+) tests containing (\d+) assertions.(\s*)(\d+) failures, (\d+) errors./
  return :amber if syntax_error_pattern.match(output)
  return :red   if output.scan(ran_pattern).any? { |res| res[3] != '0' || res[4] != '0' }
  # The count of tests run is what keeps a kata holding none out of green.
  # clojure.test prints the same zero failures and zero errors either way, so
  # without it a run that proved nothing reads as a pass.
  return :green if output.scan(ran_pattern).any? { |res| res[3] == '0' && res[4] == '0' && res[0] != '0' }
  return :amber
}

